import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';

const Header: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const location = useLocation();
  const isHome = location.pathname === '/';

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: 'Collections', path: '/#collections' },
    { name: 'About', path: '/#about' },
    { name: 'Blog', path: '/blog' },
    { name: 'Contact', path: '/contact' },
  ];

  const headerStyles = isScrolled 
    ? 'bg-white shadow-sm py-4' 
    : isHome ? 'bg-transparent py-6' : 'bg-white py-6';

  const logoColor = !isScrolled && isHome ? 'text-white' : 'text-meridian-warmBlack';
  const navLinkColor = !isScrolled && isHome ? 'text-white' : 'text-meridian-warmBlack';

  return (
    <header className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${headerStyles}`}>
      <div className="container mx-auto px-6 lg:px-12 flex justify-between items-center">
        <Link to="/" className={`font-display text-2xl tracking-extrawide uppercase font-medium ${logoColor}`}>
          Meridian Optics
        </Link>

        <nav className="hidden md:flex space-x-10">
          {navLinks.map((link) => (
