  return (
    <div className="flex items-center gap-3 group">
      <svg width="42" height="42" viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg" className="transition-all duration-500 transform group-hover:scale-110">
        {/* Main A Shape */}
        <path d="M50 15L25 85H35L40 70H60L65 85H75L50 15Z" fill={color} />
        {/* Superset 2 */}
        <path d="M72 15H82V18L77 26H82V29H72V26L77 18H72V15Z" fill={color} />
        {/* Glasses bridge / integration */}
        <path d="M42 55C42 50 32 50 32 55C32 60 42 60 42 55Z" stroke={color} strokeWidth="2.5" />
        <path d="M68 55C68 50 58 50 58 55C58 60 68 60 68 55Z" stroke={color} strokeWidth="2.5" />
        <path d="M42 55H58" stroke={color} strokeWidth="2.5" />
        {/* Bridge to temples */}
        <path d="M32 55H28" stroke={color} strokeWidth="2" />
        <path d="M68 55H72" stroke={color} strokeWidth="2" />
      </svg>
      <div className={`font-display text-2xl tracking-[0.25em] uppercase font-medium transition-all duration-500 ${!isScrolled && isHome ? 'text-white' : 'text-meridian-warmBlack'}`}>
        A<sup>2</sup>OPTICS
      </div>
    </div>
  );
};

const Header: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const location = useLocation();
  const isHome = location.pathname === '/';

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: 'Collections', path: '/#collections' },
    { name: 'About', path: '/#about' },
    { name: 'Blog', path: '/blog' },
    { name: 'Contact', path: '/contact' },
