  const contentIndex = index % placeholderContent.length;

  const displayTitle = isPlaceholder ? placeholderContent[contentIndex].title : post.title;
  const displayExcerpt = isPlaceholder ? placeholderContent[contentIndex].excerpt : post.excerpt;
  const fallback = eyewearFallbacks[index % eyewearFallbacks.length];

  const [imgSrc, setImgSrc] = useState(post.imageUrl || fallback);

  return (
    <div className="group cursor-pointer">
      <div className="aspect-[16/9] overflow-hidden mb-8 bg-meridian-lightGrey relative">
        <img 
          src={imgSrc} 
          alt={displayTitle} 
          onError={() => setImgSrc(fallback)}
          className="w-full h-full object-cover transition-transform duration-700"
        />
      </div>
      <div className="space-y-4">
