import { Resend } from 'resend';
import { EmailTemplate } from '../components/EmailTemplate';

/**
 * Server-side handler for sending emails via Resend.
 * This route expects a POST request with the form data as JSON.
 * 
 * Note: RESEND_API_KEY should be set in your environment variables.
 */

const resend = new Resend(process.env.RESEND_API_KEY);

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const { name, practice, email, phone, location, interest, message } = body;

    // Basic validation
    if (!name || !email || !message) {
      return new Response(
        JSON.stringify({ error: 'Missing required fields' }), 
        { status: 400, headers: { 'Content-Type': 'application/json' } }
      );
    }

    const { data, error } = await resend.emails.send({
      from: 'A2OPTICS Contact <onboarding@resend.dev>',
      to: ['info@a2optics.com'], // Replace with your verified recipient
      subject: `New Stockist Enquiry: ${practice}`,
      react: EmailTemplate({ 
        name, 
        practice, 
        email, 
        phone, 
        location, 
        interest, 
        message 
      }),
    });

    if (error) {
      return new Response(
        JSON.stringify({ error }), 
        { status: 500, headers: { 'Content-Type': 'application/json' } }
      );
    }

    return new Response(
      JSON.stringify(data), 
      { status: 200, headers: { 'Content-Type': 'application/json' } }
    );
  } catch (error) {
    return new Response(
      JSON.stringify({ error: 'Internal Server Error' }), 
      { status: 500, headers: { 'Content-Type': 'application/json' } }
    );
  }
}

