import { Resend } from 'resend';
import { EmailTemplate } from '../components/EmailTemplate';

/**
 * Server-side handler for sending emails via Resend.
 * This route expects a POST request with the form data as JSON.
 * 
 * Note: RESEND_API_KEY should be set in your environment variables.
 * Resend SDK requires the API Key during initialization.
 */

// Use a standard environment variable name for the API key
const resend = new Resend(process.env.RESEND_API_KEY || process.env.API_KEY);

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const { name, practice, email, phone, location, interest, message } = body;

    // Basic validation
    if (!name || !email || !message) {
      return new Response(
        JSON.stringify({ error: 'Missing required fields' }), 
        { status: 400, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // Attempt to send email
    const { data, error } = await resend.emails.send({
      // Resend testing requires sending FROM a verified domain or 'onboarding@resend.dev'
      from: 'A2OPTICS Contact <onboarding@resend.dev>',
      // Resend testing requires sending TO the email associated with the Resend account
      to: ['info@a2optics.com'], 
      subject: `New Stockist Enquiry: ${practice}`,
      react: EmailTemplate({ 
        name, 
        practice, 
        email, 
        phone, 
        location, 
        interest, 
        message 
      }),
    });

    if (error) {
      console.error('Resend API Error:', error);
      return new Response(
        JSON.stringify({ error: error.message || 'Resend failed to deliver the email.' }), 
        { status: 500, headers: { 'Content-Type': 'application/json' } }
      );
    }

    return new Response(
      JSON.stringify(data), 
      { status: 200, headers: { 'Content-Type': 'application/json' } }
    );
  } catch (error: any) {
    console.error('Server Internal Error:', error);
    return new Response(
      JSON.stringify({ error: 'Internal Server Error: ' + error.message }), 
      { status: 500, headers: { 'Content-Type': 'application/json' } }
    );
  }
}

