import { Resend } from 'resend';
import { EmailTemplate } from '../components/EmailTemplate';

/**
 * Server-side handler for sending emails via Resend.
 * This route expects a POST request with the form data as JSON.
 */

// Initialize Resend with the provided key or from environment variables
const resend = new Resend(process.env.RESEND_API_KEY || process.env.API_KEY);

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const { name, practice, email, phone, location, interest, message } = body;

    // Server-side validation fallback
    if (!name || !email || !message || !practice) {
      return new Response(
        JSON.stringify({ error: 'Required fields are missing.' }), 
        { status: 400, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // Attempt to send email using Resend
    // Important: 'onboarding@resend.dev' is for testing.
    // Ensure info@a2optics.com is verified in the Resend dashboard.
    const result = await resend.emails.send({
      from: 'A2OPTICS Contact <onboarding@resend.dev>',
      to: ['info@a2optics.com'], 
      replyTo: email,
      subject: `New Stockist Enquiry: ${practice}`,
      react: EmailTemplate({ 
        name, 
        practice, 
        email, 
        phone, 
        location, 
        interest, 
        message 
      }),
    });

    if (result.error) {
      console.error('Resend SDK Error:', result.error);
      return new Response(
        JSON.stringify({ 
          error: result.error.message || 'Resend service failed to deliver the message.',
          details: result.error
        }), 
        { status: 500, headers: { 'Content-Type': 'application/json' } }
      );
    }

    return new Response(
      JSON.stringify({ success: true, data: result.data }), 
      { status: 200, headers: { 'Content-Type': 'application/json' } }
    );
  } catch (error: any) {
    console.error('API Send Error:', error);
    return new Response(
      JSON.stringify({ error: 'A server error occurred: ' + (error.message || 'Internal Server Error') }), 
      { status: 500, headers: { 'Content-Type': 'application/json' } }
    );
  }
}

