import { Resend } from 'resend';
import { EmailTemplate } from '../../../components/EmailTemplate';

/**
 * Server-side API route for Resend (App Router).
 * 
 * Troubleshooting "Not Sending":
 * 1. Ensure the API_KEY environment variable is correctly set in your hosting provider (e.g. Vercel).
 * 2. If using 'onboarding@resend.dev', Resend ONLY allows sending to the email used for account signup.
 * 3. Verify that 'info@a2optics.com' is either your signup email or part of a verified domain in Resend.
 */

const resend = new Resend(process.env.RESEND_API_KEY || process.env.API_KEY);

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const { name, practice, email, phone, location, interest, message } = body;

    if (!name || !email || !message || !practice) {
      return new Response(
        JSON.stringify({ error: 'Required fields are missing: name, email, practice, or message.' }),
        { status: 400, headers: { 'Content-Type': 'application/json' } }
      );
    }

    const { data, error } = await resend.emails.send({
      from: 'A2OPTICS Contact <onboarding@resend.dev>',
      to: ['info@a2optics.com'],
      replyTo: email,
      subject: `Stockist Enquiry: ${practice}`,
      react: EmailTemplate({ 
        name, 
        practice, 
        email, 
        phone, 
        location, 
        interest, 
        message 
      }),
    });

    if (error) {
      console.error('Resend Delivery Error:', error);
      return new Response(
        JSON.stringify({ 
          error: error.message,
          code: error.name,
          suggestion: "Ensure 'info@a2optics.com' is a verified recipient or your account signup email if using the test domain."
        }),
        { status: 500, headers: { 'Content-Type': 'application/json' } }
      );
    }

    return new Response(
      JSON.stringify({ success: true, id: data?.id }),
      { status: 200, headers: { 'Content-Type': 'application/json' } }
    );
  } catch (err: any) {
    console.error('App Route Exception:', err);
    return new Response(
      JSON.stringify({ error: 'Internal server error: ' + err.message }),
      { status: 500, headers: { 'Content-Type': 'application/json' } }
    );
  }
}

