import React, { useState } from 'react';
import Section from '../components/Section';
import { Mail, Phone, MapPin, Loader2, CheckCircle2, ArrowLeft, AlertCircle } from 'lucide-react';
import { Link } from 'react-router-dom';

interface FormErrors {
  name?: string;
  practice?: string;
  email?: string;
  phone?: string;
  message?: string;
}

const Contact: React.FC = () => {
  const [formState, setFormState] = useState({
    name: '',
    practice: '',
    email: '',
    phone: '',
    location: 'Republic of Ireland',
    interest: 'Becoming a stockist',
    message: ''
  });

  const [errors, setErrors] = useState<FormErrors>({});
  const [status, setStatus] = useState<'idle' | 'submitting' | 'success' | 'error'>('idle');
  const [errorMessage, setErrorMessage] = useState('');

  const validateEmail = (email: string) => {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  };

  const validatePhone = (phone: string) => {
    if (!phone) return true; // Optional field
    return /^[\d\s+()-]{7,20}$/.test(phone);
  };

  const validateForm = (): boolean => {
    const newErrors: FormErrors = {};

    // Name Validation
    if (!formState.name.trim()) {
      newErrors.name = 'Full name is required';
    } else if (formState.name.trim().length < 2) {
      newErrors.name = 'Please enter a valid full name';
    }

    // Practice Validation
    if (!formState.practice.trim()) {
      newErrors.practice = 'Practice / Business name is required';
    }

    // Email Validation
    if (!formState.email.trim()) {
      newErrors.email = 'Email address is required';
    } else if (!validateEmail(formState.email)) {
      newErrors.email = 'Please enter a valid professional email address';
    }

    // Phone Validation (Optional but formatted)
    if (formState.phone && !validatePhone(formState.phone)) {
      newErrors.phone = 'Please enter a valid phone number';
    }

    // Message Validation
    if (!formState.message.trim()) {
      newErrors.message = 'Please provide details about your enquiry';
    } else if (formState.message.trim().length < 15) {
      newErrors.message = 'Please provide a bit more detail (min 15 characters)';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) {
      const firstError = document.querySelector('[aria-invalid="true"]');
      firstError?.scrollIntoView({ behavior: 'smooth', block: 'center' });
      return;
    }

    setStatus('submitting');
    setErrorMessage('');

    try {
      const response = await fetch('/api/send', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formState),
      });

      const result = await response.json().catch(() => ({}));

      if (!response.ok) {
        // If it's a 404, it means the API route isn't hosted correctly in this specific environment
        if (response.status === 404) {
          throw new Error('The email service is currently unavailable. Please reach out to info@a2optics.com directly.');
        }
        throw new Error(result.error || `Error ${response.status}: ${response.statusText}`);
      }

      setStatus('success');
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } catch (error) {
      console.error('Contact Form Error:', error);
      setStatus('error');
      setErrorMessage(error instanceof Error ? error.message : 'An unexpected error occurred. Please try contacting us directly at info@a2optics.com.');
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormState(prev => ({ ...prev, [name]: value }));

    // Real-time error clearing
    if (errors[name as keyof FormErrors]) {
      setErrors(prev => ({ ...prev, [name]: undefined }));
    }
  };

  const inputBaseClasses = "w-full bg-white border px-4 py-4 focus:outline-none transition-all font-light text-sm disabled:opacity-50";
  const errorClasses = "border-red-500 ring-1 ring-red-500 focus:border-red-500";
  const defaultClasses = "border-meridian-borderGrey focus:border-meridian-gold hover:border-meridian-mediumGrey";

  return (
    <div className="pt-24 lg:pt-32">
      <Section id="contact-hero" className="pb-0!">
        <div className="max-w-3xl mb-16">
          <span className="text-xs tracking-extrawide uppercase font-medium text-meridian-gold block mb-6">Connect</span>
          <h1 className="font-display text-5xl md:text-7xl font-light leading-tight mb-8">Let's Talk</h1>
          <p className="text-lg text-meridian-charcoal font-light leading-relaxed">
            Whether you're interested in becoming a stockist or have questions about our collections, we'd love to hear from you. We typically respond to all enquiries within one business day.
          </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-20">
          <div className="relative">
            {status === 'success' ? (
              <div className="bg-meridian-offWhite border border-meridian-borderGrey p-12 lg:p-20 text-center space-y-8 animate-in fade-in zoom-in-95 duration-700">
                <div className="flex justify-center">
                  <div className="w-20 h-20 bg-meridian-gold/10 rounded-full flex items-center justify-center">
                    <CheckCircle2 className="w-10 h-10 text-meridian-gold stroke-[1.5px]" />
                  </div>
                </div>
                <div className="space-y-4">
                  <h3 className="font-display text-4xl font-light">Enquiry Sent</h3>
                  <p className="text-sm text-meridian-charcoal font-light leading-relaxed max-w-sm mx-auto opacity-80">
                    Thank you for reaching out. Your enquiry has been successfully delivered. Andrew will review your details and contact you within 24 hours.
                  </p>
                </div>
                <div className="pt-6 flex flex-col sm:flex-row items-center justify-center gap-6">
                  <Link 
                    to="/"
                    className="text-[10px] tracking-widest uppercase font-bold text-meridian-warmBlack hover:text-meridian-gold transition-colors flex items-center gap-2"
                  >
                    <ArrowLeft size={12} />
                    Back to Home
                  </Link>
                  <button 
                    onClick={() => {
                      setStatus('idle');
                      setFormState(prev => ({ ...prev, message: '' }));
                    }}
                    className="text-[10px] tracking-widest uppercase font-bold border-b border-meridian-warmBlack pb-1 hover:text-meridian-gold hover:border-meridian-gold transition-all"
                  >
                    Send another message
                  </button>
                </div>
              </div>
            ) : (
              <form onSubmit={handleSubmit} className="space-y-8" noValidate>
                {status === 'error' && (
                  <div className="p-4 bg-red-50 border border-red-100 text-red-700 text-[11px] leading-relaxed tracking-wide flex items-start gap-3 animate-in fade-in slide-in-from-top-2">
                    <AlertCircle size={16} className="mt-0.5 shrink-0" />
                    <div>
                      <strong className="block mb-1 text-xs">Submission Error</strong>
                      {errorMessage}
                    </div>
                  </div>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-2">
                    <label className="text-[10px] tracking-widest uppercase font-medium text-meridian-mediumGrey">Full Name*</label>
                    <input 
                      disabled={status === 'submitting'}
                      name="name"
                      type="text"
                      placeholder="e.g. Jane Doe"
                      value={formState.name}
                      onChange={handleChange}
                      aria-invalid={!!errors.name}
                      className={`${inputBaseClasses} ${errors.name ? errorClasses : defaultClasses}`}
                    />
                    {errors.name && <p className="text-[10px] text-red-500 mt-1 font-medium">{errors.name}</p>}
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] tracking-widest uppercase font-medium text-meridian-mediumGrey">Practice / Business Name*</label>
                    <input 
                      disabled={status === 'submitting'}
                      name="practice"
                      type="text"
                      placeholder="e.g. Vision Care Dublin"
                      value={formState.practice}
                      onChange={handleChange}
                      aria-invalid={!!errors.practice}
                      className={`${inputBaseClasses} ${errors.practice ? errorClasses : defaultClasses}`}
                    />
                    {errors.practice && <p className="text-[10px] text-red-500 mt-1 font-medium">{errors.practice}</p>}
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-2">
                    <label className="text-[10px] tracking-widest uppercase font-medium text-meridian-mediumGrey">Email Address*</label>
                    <input 
                      disabled={status === 'submitting'}
