                      type="email"
                      placeholder="jane@example.com"
                      value={formState.email}
                      onChange={handleChange}
                      aria-invalid={!!errors.email}
                      className={`${inputBaseClasses} ${errors.email ? errorClasses : defaultClasses}`}
                    />
                    {errors.email && <p className="text-[10px] text-red-500 mt-1 font-medium">{errors.email}</p>}
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] tracking-widest uppercase font-medium text-meridian-mediumGrey">Phone Number</label>
                    <input 
                      disabled={status === 'submitting'}
