                    <div className="relative">
                      <select 
                        disabled={status === 'submitting'}
                        name="location"
                        value={formState.location}
                        onChange={handleChange}
                        className={`${inputBaseClasses} ${defaultClasses} appearance-none pr-10`}
                      >
                        <option>Republic of Ireland</option>
