import React, { useState, useRef } from 'react';
import Section from '../components/Section';
import { Mail, Phone, MapPin, Loader2, CheckCircle2, AlertCircle, ExternalLink, Copy, Check, ShieldCheck, Send } from 'lucide-react';
import { Link } from 'react-router-dom';

interface FormErrors {
  name?: string;
  practice?: string;
  email?: string;
  phone?: string;
  message?: string;
}

const Contact: React.FC = () => {
  const [formState, setFormState] = useState({
    name: '',
    practice: '',
    email: '',
    phone: '',
    location: 'Republic of Ireland',
    interest: 'Becoming a stockist',
    message: '',
    _gotcha: '' 
  });

  const [errors, setErrors] = useState<FormErrors>({});
  const [status, setStatus] = useState<'idle' | 'submitting' | 'success' | 'error'>('idle');
  const [serverError, setServerError] = useState<string>('');
  const [copied, setCopied] = useState(false);
  const hiddenFormRef = useRef<HTMLFormElement>(null);

  /**
   * Verified Formspree Endpoint
   * Standard URL for email-based submissions.
   */
  const FORMSPREE_ENDPOINT = "https://formspree.io/info@a2optics.com";

  const validateEmail = (email: string) => {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  };

  const validateForm = (): boolean => {
    const newErrors: FormErrors = {};
    if (!formState.name.trim()) newErrors.name = 'Full name is required';
    if (!formState.practice.trim()) newErrors.practice = 'Practice name is required';
    if (!formState.email.trim()) {
      newErrors.email = 'Email address is required';
    } else if (!validateEmail(formState.email)) {
      newErrors.email = 'Please enter a valid professional email address';
    }
    if (!formState.message.trim()) {
      newErrors.message = 'Please provide details about your enquiry';
    } else if (formState.message.trim().length < 10) {
      newErrors.message = 'Please provide a bit more detail';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (formState._gotcha) { setStatus('success'); return; }
    if (!validateForm()) return;

    setStatus('submitting');
    setServerError('');

    try {
      const response = await fetch(FORMSPREE_ENDPOINT, {
        method: 'POST',
        headers: {
          'Accept': 'application/json',
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          name: formState.name,
          practice: formState.practice,
          email: formState.email,
          _replyto: formState.email,
          phone: formState.phone,
          location: formState.location,
          message: formState.message,
          _subject: `New Stockist Enquiry: ${formState.practice}`
        }),
      });

      const data = await response.json();

      if (response.ok) {
        setStatus('success');
        window.scrollTo({ top: 0, behavior: 'smooth' });
      } else {
        // Handle Formspree specific "Not Set Up" or "Account Verification" issues
        const errorMsg = data.error || 'Connection interrupted.';
        if (errorMsg.toLowerCase().includes('set up') || errorMsg.toLowerCase().includes('verify')) {
          setServerError("Formspree requires a manual 'handshake' to activate this domain.");
        } else {
          setServerError(errorMsg);
        }
        setStatus('error');
      }
