import React, { useState } from 'react';
import Section from '../components/Section';
import { Mail, Phone, MapPin, Loader2, CheckCircle2, AlertCircle, ExternalLink, Copy, Check, Send } from 'lucide-react';
import { Link } from 'react-router-dom';

interface FormErrors {
  name?: string;
  practice?: string;
  email?: string;
  phone?: string;
  message?: string;
}

const Contact: React.FC = () => {
  const [formState, setFormState] = useState({
    name: '',
    practice: '',
    email: '',
    phone: '',
    location: 'Republic of Ireland',
    interest: 'Becoming a stockist',
    message: ''
  });

  const [errors, setErrors] = useState<FormErrors>({});
  const [status, setStatus] = useState<'idle' | 'submitting' | 'success' | 'error'>('idle');
  const [serverErrorMessage, setServerErrorMessage] = useState<string>('');
  const [copied, setCopied] = useState(false);

  const FORMSPREE_ENDPOINT = "https://formspree.io/f/meegowwv";

  const validateEmail = (email: string) => {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  };

  const validateForm = (): boolean => {
    const newErrors: FormErrors = {};
    if (!formState.name.trim()) newErrors.name = 'Full name is required';
    if (!formState.practice.trim()) newErrors.practice = 'Practice name is required';
    if (!formState.email.trim()) {
      newErrors.email = 'Email address is required';
    } else if (!validateEmail(formState.email)) {
      newErrors.email = 'Please enter a valid professional email address';
    }
    if (!formState.message.trim()) {
      newErrors.message = 'Please provide details about your enquiry';
    } else if (formState.message.trim().length < 10) {
      newErrors.message = 'Please provide a bit more detail';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!validateForm()) return;

    setStatus('submitting');
    setServerErrorMessage('');

    const formData = new FormData(e.currentTarget);

    try {
      const response = await fetch(FORMSPREE_ENDPOINT, {
        method: 'POST',
        body: formData,
        headers: {
          'Accept': 'application/json'
        }
      });

      if (response.ok) {
        setStatus('success');
        setFormState({
          name: '',
          practice: '',
          email: '',
          phone: '',
          location: 'Republic of Ireland',
          interest: 'Becoming a stockist',
          message: ''
        });
        window.scrollTo({ top: 0, behavior: 'smooth' });
      } else {
        const data = await response.json();
        if (data && Object.prototype.hasOwnProperty.call(data, 'errors')) {
          setServerErrorMessage(data["errors"].map((error: any) => error["message"]).join(", "));
        } else {
          setServerErrorMessage("There was a problem submitting your enquiry. Please try again or use the manual link.");
        }
        setStatus('error');
      }
    } catch (error) {
      setServerErrorMessage("A network connectivity issue occurred. Please check your connection or use the direct email link below.");
      setStatus('error');
    }
  };

  const handleCopy = () => {
    const text = `Name: ${formState.name}\nPractice: ${formState.practice}\nLocation: ${formState.location}\nEmail: ${formState.email}\nPhone: ${formState.phone}\nEnquiry: ${formState.message}`;
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormState(prev => ({ ...prev, [name]: value }));
    if (errors[name as keyof FormErrors]) {
      setErrors(prev => ({ ...prev, [name]: undefined }));
    }
  };

  const mailtoLink = `mailto:info@a2optics.com?subject=Enquiry for Meridian Optics from ${formState.practice}&body=Hello Andrew,%0A%0AMy name is ${formState.name} from ${formState.practice} in ${formState.location}.%0A%0AEnquiry Details: ${formState.message.replace(/\n/g, '%0A')}%0A%0AContact: ${formState.phone || 'N/A'}`;

  return (
    <div className="pt-24 lg:pt-32">
      <Section id="contact-hero" className="pb-0!">
        <div className="max-w-3xl mb-16">
          <span className="text-xs tracking-extrawide uppercase font-bold text-meridian-gold block mb-6">Partnership</span>
          <h1 className="font-display text-5xl md:text-7xl font-light leading-tight mb-8">Initiate <span className="italic">Dialogue</span></h1>
          <p className="text-lg text-meridian-charcoal font-light leading-relaxed">
            Independent practices deserve a partner with a specific vision. Reach out below to begin a conversation about curating a unique selection for your clients.
          </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-20">
          <div className="relative">
            {status === 'success' ? (
              <div className="bg-meridian-offWhite border border-meridian-borderGrey p-12 lg:p-20 text-center space-y-8 animate-in fade-in duration-700">
                <div className="flex justify-center">
                  <div className="w-20 h-20 bg-meridian-gold/10 rounded-full flex items-center justify-center">
                    <CheckCircle2 className="w-10 h-10 text-meridian-gold stroke-[1px]" />
                  </div>
                </div>

                <div className="space-y-4">
                  <h3 className="font-display text-4xl font-light">Enquiry Received</h3>
                  <p className="text-sm text-meridian-charcoal opacity-70 leading-relaxed">
                    Thank you. Your details have been transmitted directly to Andrew. We aim to respond to all professional enquiries within 24 hours.
                  </p>
                </div>

                <div className="pt-4 flex flex-col items-center gap-6">
                  <Link to="/" className="text-[10px] tracking-widest uppercase font-bold text-meridian-warmBlack border-b border-black pb-1 hover:text-meridian-gold hover:border-meridian-gold transition-colors">Back to Home</Link>
                  <button onClick={() => setStatus('idle')} className="text-[10px] tracking-widest uppercase font-bold text-meridian-mediumGrey hover:text-meridian-warmBlack">Send another message</button>
                </div>
              </div>
            ) : (
              <form onSubmit={handleSubmit} className="space-y-6">
                {status === 'error' && (
                  <div className="p-8 bg-white border border-meridian-borderGrey text-meridian-charcoal text-[11px] leading-relaxed animate-in slide-in-from-top-4 duration-500 mb-8 shadow-sm">
                    <div className="flex items-start gap-5">
                      <div className="bg-meridian-gold/10 p-2 rounded-full shrink-0">
                        <AlertCircle size={20} className="text-meridian-gold" />
                      </div>
                      <div className="space-y-5 flex-grow">
                        <div>
                          <strong className="block mb-1 text-xs tracking-widest uppercase text-meridian-warmBlack">Update</strong>
                          <p className="opacity-80">{serverErrorMessage}</p>
                        </div>
                        <div className="flex flex-col sm:flex-row gap-3 pt-2">
                          <a href={mailtoLink} className="flex-grow inline-flex items-center justify-center gap-2 bg-meridian-warmBlack text-white px-6 py-4 text-[10px] tracking-widest uppercase font-bold hover:bg-meridian-gold transition-colors">Send via Mail App <ExternalLink size={12} /></a>
                          <button type="button" onClick={handleCopy} className="inline-flex items-center justify-center gap-2 border border-meridian-borderGrey bg-white px-6 py-4 text-[10px] tracking-widest uppercase font-bold hover:bg-meridian-offWhite transition-all">{copied ? 'Data Copied' : 'Copy Data'}</button>
                        </div>
                      </div>
                    </div>
                  </div>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-1">
                    <label className="text-[10px] tracking-widest uppercase font-medium text-meridian-mediumGrey">Full Name*</label>
                    <input name="name" type="text" required placeholder="e.g. Jane Smith" value={formState.name} onChange={handleChange} className={`w-full bg-white border px-4 py-4 text-sm focus:outline-none transition-all ${errors.name ? 'border-red-500 ring-1 ring-red-500' : 'border-meridian-borderGrey focus:border-meridian-gold'}`} />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] tracking-widest uppercase font-medium text-meridian-mediumGrey">Practice Name*</label>
                    <input name="practice" type="text" required placeholder="e.g. Vision Care" value={formState.practice} onChange={handleChange} className={`w-full bg-white border px-4 py-4 text-sm focus:outline-none transition-all ${errors.practice ? 'border-red-500 ring-1 ring-red-500' : 'border-meridian-borderGrey focus:border-meridian-gold'}`} />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-1">
                    <label className="text-[10px] tracking-widest uppercase font-medium text-meridian-mediumGrey">Work Email*</label>
                    <input name="email" type="email" required placeholder="jane@practice.com" value={formState.email} onChange={handleChange} className={`w-full bg-white border px-4 py-4 text-sm focus:outline-none transition-all ${errors.email ? 'border-red-500 ring-1 ring-red-500' : 'border-meridian-borderGrey focus:border-meridian-gold'}`} />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] tracking-widest uppercase font-medium text-meridian-mediumGrey">Contact Number</label>
                    <input name="phone" type="tel" placeholder="Optional" value={formState.phone} onChange={handleChange} className="w-full bg-white border border-meridian-borderGrey px-4 py-4 text-sm focus:outline-none focus:border-meridian-gold" />
                  </div>
                </div>

                <div className="space-y-1">
                  <label className="text-[10px] tracking-widest uppercase font-medium text-meridian-mediumGrey">Enquiry Details*</label>
                  <textarea name="message" rows={5} required value={formState.message} onChange={handleChange} className={`w-full bg-white border px-4 py-4 text-sm focus:outline-none transition-all resize-none ${errors.message ? 'border-red-500 ring-1 ring-red-500' : 'border-meridian-borderGrey focus:border-meridian-gold'}`} placeholder="Tell us about your practice and your interest in our collections..."></textarea>
                </div>

                <button type="submit" disabled={status === 'submitting'} className="w-full bg-meridian-warmBlack text-white py-5 text-[10px] tracking-extrawide uppercase font-bold hover:bg-meridian-gold transition-all duration-300 flex items-center justify-center gap-3 disabled:bg-meridian-mediumGrey shadow-xl active:scale-[0.98]">
                  {status === 'submitting' ? <><Loader2 size={16} className="animate-spin" /> Transmitting...</> : <><Send size={14} /> Send Professional Enquiry</>}
                </button>
              </form>
            )}
          </div>

          <div className="space-y-12 lg:pl-10">
            <h3 className="font-display text-3xl font-light">Meridian Access</h3>
            <div className="space-y-8">
              <div className="flex items-start gap-6 group">
                <div className="w-12 h-12 border border-meridian-borderGrey flex items-center justify-center shrink-0 group-hover:border-meridian-gold transition-colors">
                  <Mail className="w-5 h-5 text-meridian-gold stroke-[1.2px]" />
                </div>
                <div>
                  <span className="block text-[10px] tracking-widest uppercase font-medium text-meridian-mediumGrey mb-1">Direct Correspondence</span>
                  <a href="mailto:info@a2optics.com" className="text-base font-light hover:text-meridian-gold transition-colors">info@meridianoptics.ie</a>
                </div>
              </div>
              <div className="flex items-start gap-6 group">
                <div className="w-12 h-12 border border-meridian-borderGrey flex items-center justify-center shrink-0 group-hover:border-meridian-gold transition-colors">
                  <Phone className="w-5 h-5 text-meridian-gold stroke-[1.2px]" />
                </div>
                <div>
                  <span className="block text-[10px] tracking-widest uppercase font-medium text-meridian-mediumGrey mb-1">Direct Line</span>
                  <a href="tel:+447703166036" className="text-base font-light hover:text-meridian-gold transition-colors">+44 (0) 7703 166036</a>
                </div>
              </div>
              <div className="flex items-start gap-6 group">
                <div className="w-12 h-12 border border-meridian-borderGrey flex items-center justify-center shrink-0 group-hover:border-meridian-gold transition-colors">
                  <MapPin className="w-5 h-5 text-meridian-gold stroke-[1.2px]" />
                </div>
                <div>
                  <span className="block text-[10px] tracking-widest uppercase font-medium text-meridian-mediumGrey mb-1">Coverage</span>
                  <span className="text-base font-light">Ireland North & South</span>
                </div>
              </div>
            </div>

            <div className="bg-meridian-warmBlack p-8 text-white mt-12 relative overflow-hidden">
              <div className="absolute top-0 right-0 w-24 h-24 bg-meridian-gold/10 -translate-y-1/2 translate-x-1/2 rounded-full"></div>
              <h4 className="text-[10px] tracking-[0.3em] uppercase font-bold text-meridian-gold mb-4 italic">Independent Heritage</h4>
              <p className="text-sm text-white/70 font-light leading-relaxed mb-6">
                Independent practices deserve an independent partner. We understand the specific clinical and commercial pressures of the Irish optical market.
              </p>
              <div className="h-[1px] bg-white/10 w-full mb-6"></div>
              <p className="text-[10px] tracking-widest uppercase font-bold">Andrew Arbuthnot • Director</p>
            </div>
          </div>
        </div>
      </Section>
    </div>
  );
};

